void mainImage(out vec4 o, vec2 I)
{
    I /= iResolution.xy;

    I = (I+vec2(10,15))/16.0;

    // Quick hack to show that this shader has sound
    float d = texture(iChannel0, I).x;
    float w = fwidth(d);
    o = vec4(smoothstep(0.5 - w, 0.5 + w, d));
}

// https://www.shadertoy.com/view/l3cfWH frequency modulation, 2025 by jt

// Testing how to use frequency modulation, e.g. to create a simple vibrato sound.
// If I understand correctly, the phase-shift must be the time-integrated actual function.

// tags: sound, vibrato, freq, mod

#define pi 3.1415926
#define tau (pi+pi)

float fm(float frequency, float modulation, float intensity, float time)
{
    float t = tau * modulation * time;
    //return sin(tau * frequency * time + pi * intensity * sin(t)); // NOTE: cos integrated is sin
    // https://www.wolframalpha.com/input?i=+integral+cos%5E3+t+dt
    return sin(tau * frequency * time + pi * intensity * (3.0*sin(t)/4.0+1.0/12.0*sin(3.0*t))); // NOTE: cos^3 integrated is (3 sin(t))/4 + 1/12 sin(3 t)
}

vec2 mainSound( int samp, float time )
{
    //return vec2(fm(440.0, 220.0, 0.25, time))*exp(-3.0*time);
    return vec2(fm(440.0, 5.0, 2.0, time))*exp(-3.0*time);
}
